#!/usr/bin/env node
// Writes kit-rounding-cases.json: what the Node usage kit's Math.round(x * 1e6) / 1e6 answers for values a half-millionth
// off a whole micro-dollar and others, so the Python twin's _round_usd is held to the same answers (FAA-110). The
// contract does not round a cost; the twins round alike so that a limit's spentUsd agrees.
//
//   node test/fixtures/make_kit_rounding_cases.mjs [--out test/fixtures/kit-rounding-cases.json]

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const out = process.argv.includes('--out') ? process.argv[process.argv.indexOf('--out') + 1] : path.join(here, 'kit-rounding-cases.json');
const values = [];
for (let k = 0; k < 3000; k += 1) values.push(k / 1e6 + 5e-7);
values.push(0, -0, 5e-7, 1.5e-6, 2.5e-6, 0.1 + 0.2, 140.47, 6.8, 1e-7, 3.3000001, 0.9999999999999999, 12345.6789995, 1e9 + 0.0000005, 0.49999999999999994e-6);
const cases = values.map((x) => ({ x, rounded: Math.round(x * 1e6) / 1e6 }));
fs.writeFileSync(out, `${JSON.stringify({ $comment: "Generated by make_kit_rounding_cases.mjs: the Node usage kit's rounding of a cost to the micro-dollar; do not edit by hand.", cases })}\n`);
console.log(`wrote ${cases.length} rounding cases to ${out}`);
